from pathlib import Path
import re
import json

ROOT = Path(__file__).resolve().parents[2]
PAGES = ROOT / 'src/pages/chapters'
files = {p: p.read_text(encoding='utf-8') for p in PAGES.rglob('*.vue')}

def path(name):
    return next(p for p in files if p.name == name + '.vue')

def replace(name, old, new, expected=None):
    p = path(name)
    count = files[p].count(old)
    assert count and (expected is None or count == expected), (name, old[:80], count)
    files[p] = files[p].replace(old, new)

def edit(name, callback):
    p = path(name)
    files[p] = callback(files[p])

def section(text, anchor, level=2):
    start = re.search(fr'<h{level}\s+id="{re.escape(anchor)}"[^>]*>', text)
    assert start, anchor
    end = re.search(fr'<h[1-{level}]\b|</div>\s*</template>\s*$', text[start.end():])
    assert end, anchor
    return start.start(), start.end() + end.start()

def move_before(name, anchor, target, level=2):
    p = path(name); text = files[p]
    a, b = section(text, anchor, level); chunk = text[a:b]
    text = text[:a] + text[b:]
    mark = re.search(fr'<h[23]\s+id="{re.escape(target)}"', text)
    assert mark, target
    files[p] = text[:mark.start()] + chunk + text[mark.start():]

