for day, data in enumerate(openings):
    p = next(p for p in files if p.name.startswith(f'Day{day}-'))
    title, eyebrow, lead, enjoy, remember = data
    html = f'''<section class="day-opening" aria-label="今日旅行建议">
      <p class="day-opening__eyebrow">{eyebrow}</p>
      <p class="day-opening__lead">{lead}</p>
      <div class="day-opening__notes">
        <p><strong>把时间留给</strong>{enjoy}</p>
        <p><strong>出发前记住</strong>{remember}</p>
      </div>
    </section>'''
    s = files[p]
    s = re.sub(r'(<h2 id="今日主题">).*?(</h2>)', lambda m: m[1]+title+m[2], s, count=1)
    if 'class="experience-card"' in s:
        s, n = re.subn(r'<section class="experience-card".*?</section>', lambda _: html, s, count=1, flags=re.S)
        assert n == 1, p
    else:
        a,b = section(s,'今日主题')
        heading = s[a:s.index('</h2>',a)+5]
        s = s[:a]+heading+'\n    '+html+'\n\n    '+s[b:]
    files[p] = s

