name='Day9-乌鲁木齐-香港'
replace(name,'起飞后关闭电子设备，优先补眠','电子设备按机组要求设置飞行模式，优先补眠')
replace(name,'若必须自驾，先在服务区或家附近休息','有困意就改由清醒驾驶员、出租车或公共交通接续，不用短暂休息证明已适合自驾')
replace(name,'须在离港后 28 日内申请退款','须在相应香港离境航段离港后 28 日内申请退款；本行程对应 10 月 2 日 HB862 离港，不从 10 月 11 日返港重新起算')

# 所有文章统一去掉版本演变口吻，保留来源日志的历史条目。
for p,s in list(files.items()):
    if p.name.startswith('04-'): continue
    s=s.replace('用户订单为最高真源','价格与预订状态以用户订单为准')
    s=s.replace('用户订单为最高真源。','价格与预订状态以用户订单为准。')
    s=s.replace('20:00 返村','20:00 从喀纳斯发车返村')
    s=s.replace('08:55 前退房','08:55 前完成退房准备，09:00 发车')
    s=s.replace('08:55 前装车退房出发','08:55 前装车退房准备，09:00 发车')
    files[p]=s

for p,s in files.items():
    if p.read_text(encoding='utf-8') != s: p.write_text(s,encoding='utf-8')
print(f'Updated daily openings and audited wording across {len(files)} chapters.')
